parameters.jsCode:
const context =
  $('Preparar entrada IA WF-015')
    .item
    .json;

const rawResponse =
  $json.output
  ?? $json.text
  ?? $json.response
  ?? $json.content
  ?? $json.message?.content
  ?? $json.choices?.[0]?.message?.content
  ?? $json;

const cleanText = (value) =>
  String(value ?? '')
    .replace(/\u0000/g, '')
    .trim();

const cleanNullableText = (value) => {
  const text =
    cleanText(value);

  return text || null;
};

const normalizeBoolean = (value) => {
  if (typeof value === 'boolean') {
    return value;
  }

  const normalized =
    cleanText(value)
      .toLowerCase();

  return [
    'true',
    '1',
    'yes',
    'si',
    'sí',
  ].includes(normalized);
};

const normalizeOptionalInteger = (value) => {
  if (
    value === null
    || value === undefined
    || value === ''
  ) {
    return null;
  }

  const number =
    Number.parseInt(
      value,
      10
    );

  return Number.isFinite(number)
    && number > 0
      ? number
      : null;
};

const normalizeConfidence = (value) => {
  const number =
    Number(value);

  if (!Number.isFinite(number)) {
    return null;
  }

  return Math.max(
    0,
    Math.min(
      1,
      number
    )
  );
};

const allowedCategories =
  new Set([
    'legal',
    'tax',
    'disciplinary',
    'fiscal',
    'social_security',
    'financial',
    'experience',
    'technical',
    'administrative',
    'entity_template',
    'signature',
    'consortium',
    'other',
  ]);

const allowedAppliesTo =
  new Set([
    'bidder',
    'legal_representative',
    'legal_entity',
    'natural_person',
    'consortium_member',
    'temporary_union_member',
    'accountant',
    'statutory_auditor',
    'technical_staff',
    'subcontractor',
    'other',
  ]);

const allowedRequirementStages =
  new Set([
    'bid_submission',
    'eligibility',
    'evaluation',
    'award',
    'contract_signing',
    'contract_execution',
    'payment',
    'other',
  ]);

const bidRequirementStages =
  new Set([
    'bid_submission',
    'eligibility',
    'evaluation',
  ]);

const baseResult = {
  opportunity_document_id:
    context.opportunity_document_id,

  organization_id:
    context.organization_id,

  opportunity_analysis_id:
    context.opportunity_analysis_id,

  process_id:
    context.process_id,

  process_reference:
    context.process_reference,

  document_name:
    context.document_name,

  primary_category:
    context.primary_category,

  extraction_id:
    context.extraction_id,

  extraction_version:
    context.extraction_version,

  model_name:
    context.ai_requirement_model,

  prompt_version:
    context.ai_requirement_prompt_version
    ?? context.prompt_version
    ?? 2,
};

const invalidResponse = (
  message,
  responsePreview
) => ({
  json: {
    ...baseResult,

    document_summary:
      null,

    requirements:
      [],

    requirements_count:
      0,

    response_valid:
      false,

    error_message:
      message,

    raw_response_preview:
      cleanText(
        responsePreview
      ).slice(
        0,
        2000
      ),

    normalized_at:
      new Date().toISOString(),
  },
});

const extractJsonObject = (text) => {
  let start =
    -1;

  let depth =
    0;

  let inString =
    false;

  let escaped =
    false;

  for (
    let index = 0;
    index < text.length;
    index += 1
  ) {
    const character =
      text[index];

    if (start === -1) {
      if (character === '{') {
        start =
          index;

        depth =
          1;
      }

      continue;
    }

    if (escaped) {
      escaped =
        false;

      continue;
    }

    if (
      inString
      && character === '\\'
    ) {
      escaped =
        true;

      continue;
    }

    if (character === '"') {
      inString =
        !inString;

      continue;
    }

    if (inString) {
      continue;
    }

    if (character === '{') {
      depth +=
        1;
    }

    if (character === '}') {
      depth -=
        1;

      if (depth === 0) {
        return text.slice(
          start,
          index + 1
        );
      }
    }
  }

  return null;
};

let parsed;

if (
  rawResponse
  && typeof rawResponse === 'object'
  && !Array.isArray(rawResponse)
) {
  parsed =
    rawResponse;
} else {
  let responseText =
    cleanText(
      rawResponse
    );

  responseText =
    responseText
      .replace(
        /^```json\s*/i,
        ''
      )
      .replace(
        /^```\s*/i,
        ''
      )
      .replace(
        /\s*```$/i,
        ''
      )
      .trim();

  let jsonCandidate =
    responseText;

  try {
    parsed =
      JSON.parse(
        jsonCandidate
      );
  } catch (directError) {
    jsonCandidate =
      extractJsonObject(
        responseText
      );

    if (!jsonCandidate) {
      return invalidResponse(
        'La IA respondió, pero no incluyó ningún objeto JSON.',
        responseText
      );
    }

    try {
      parsed =
        JSON.parse(
          jsonCandidate
        );
    } catch (extractedError) {
      return invalidResponse(
        `La IA no devolvió JSON válido: ${extractedError.message}`,
        responseText
      );
    }
  }
}

if (
  !parsed
  || typeof parsed !== 'object'
  || Array.isArray(parsed)
) {
  return invalidResponse(
    'La respuesta de la IA no contiene un objeto JSON válido.',
    rawResponse
  );
}

if (
  !Array.isArray(
    parsed.requirements
  )
) {
  return invalidResponse(
    'La respuesta no contiene la propiedad requirements como arreglo.',
    rawResponse
  );
}

const requirements =
  parsed.requirements
    .map(
      (
        requirement,
        index
      ) => {
        if (
          !requirement
          || typeof requirement !== 'object'
          || Array.isArray(requirement)
        ) {
          return null;
        }

        const name =
          cleanText(
            requirement
              .requirement_name
          );

        const evidence =
          cleanNullableText(
            requirement
              .evidence_text
          );

        if (
          !name
          || !evidence
        ) {
          return null;
        }

        const categoryCandidate =
          cleanText(
            requirement
              .requirement_category
          )
            .toLowerCase();

        const category =
          allowedCategories.has(
            categoryCandidate
          )
            ? categoryCandidate
            : 'other';

        const appliesCandidate =
          cleanText(
            requirement
              .applies_to
          )
            .toLowerCase();

        const appliesTo =
          allowedAppliesTo.has(
            appliesCandidate
          )
            ? appliesCandidate
            : 'other';

        const stageCandidate =
          cleanText(
            requirement
              .requirement_stage
          )
            .toLowerCase();

        const requirementStage =
          allowedRequirementStages.has(
            stageCandidate
          )
            ? stageCandidate
            : 'other';

        const isBidRequirement =
          bidRequirementStages.has(
            requirementStage
          );

        const conditionText =
          cleanNullableText(
            requirement
              .condition_text
          );

        /*
         * Si la IA identifica una condición,
         * el requisito no debe almacenarse como
         * obligatorio en todos los casos.
         */
        const mandatory =
          conditionText
            ? false
            : (
                requirement.mandatory
                  === undefined
                    ? true
                    : normalizeBoolean(
                        requirement
                          .mandatory
                      )
              );

        return {
          requirement_category:
            category,

          requirement_name:
            name,

          normalized_document_type:
            cleanNullableText(
              requirement
                .normalized_document_type
            ),

          requirement_description:
            cleanNullableText(
              requirement
                .requirement_description
            ),

          mandatory,

          condition_text:
            conditionText,

          maximum_age_days:
            normalizeOptionalInteger(
              requirement
                .maximum_age_days
            ),

          requires_signature:
            normalizeBoolean(
              requirement
                .requires_signature
            ),

          requires_entity_template:
            normalizeBoolean(
              requirement
                .requires_entity_template
            ),

          requires_original:
            normalizeBoolean(
              requirement
                .requires_original
            ),

          requires_notarization:
            normalizeBoolean(
              requirement
                .requires_notarization
            ),

          requires_translation:
            normalizeBoolean(
              requirement
                .requires_translation
            ),

          applies_to:
            appliesTo,

          requirement_stage:
            requirementStage,

          is_bid_requirement:
            isBidRequirement,

          source_page:
            normalizeOptionalInteger(
              requirement
                .source_page
            ),

          source_section:
            cleanNullableText(
              requirement
                .source_section
            ),

          evidence_text:
            evidence.slice(
              0,
              450
            ),

          confidence_score:
            normalizeConfidence(
              requirement
                .confidence_score
            ),

          source_order:
            index + 1,
        };
      }
    )
    .filter(Boolean);

return {
  json: {
    ...baseResult,

    document_summary:
      cleanNullableText(
        parsed.document_summary
      ),

    requirements,

    requirements_count:
      requirements.length,

    response_valid:
      true,

    error_message:
      null,

    raw_response_preview:
      null,

    normalized_at:
      new Date().toISOString(),
  },
};

